  // src/methods/get.js
  function getSheetIndex(index2) {
    for (let i2 = 0; i2 < store_default.luckysheetfile.length; i2++) {
      if (store_default.luckysheetfile[i2]["index"] == index2) {
        return i2;
      }
    }
    return null;
  }
  function getRangetxt(sheetIndex, range2, currentIndex) {
    let sheettxt = "";
    if (currentIndex == null) {
      currentIndex = store_default.currentSheetIndex;
    }
    if (sheetIndex != currentIndex) {
      sheettxt = store_default.luckysheetfile[getSheetIndex(sheetIndex)].name.replace(/'/g, "''");
      if (/^[:A-Z_a-z\u00C0-\u00D6\u00D8-\u00F6\u00F8-\u02FF\u0370-\u037D\u037F-\u1FFF\u200C-\u200D\u2070-\u218F\u2C00-\u2FEF\u3001-\uD7FF\uF900-\uFDCF\uFDF0-\uFFFD][:A-Z_a-z\u00C0-\u00D6\u00D8-\u00F6\u00F8-\u02FF\u0370-\u037D\u037F-\u1FFF\u200C-\u200D\u2070-\u218F\u2C00-\u2FEF\u3001-\uD7FF\uF900-\uFDCF\uFDF0-\uFFFD\-.0-9\u00B7\u0300-\u036F\u203F-\u2040]*$/.test(sheettxt)) {
        sheettxt = sheettxt + "!";
      } else {
        sheettxt = "'" + sheettxt + "'!";
      }
    }
    let row0 = range2["row"][0], row1 = range2["row"][1];
    let column0 = range2["column"][0], column1 = range2["column"][1];
    if (row0 == null && row1 == null) {
      return sheettxt + chatatABC(column0) + ":" + chatatABC(column1);
    } else if (column0 == null && column1 == null) {
      return sheettxt + (row0 + 1) + ":" + (row1 + 1);
    } else {
      if (column0 == column1 && row0 == row1) {
        return sheettxt + chatatABC(column0) + (row0 + 1);
      } else {
        return sheettxt + chatatABC(column0) + (row0 + 1) + ":" + chatatABC(column1) + (row1 + 1);
      }
    }
  }
  function getluckysheet_select_save() {
    return store_default.luckysheet_select_save;
  }
  function getluckysheetfile(plugin) {
    if (plugin) {
      store_default.luckysheetfile.forEach((file) => {
        if (!!file.chart) {
          file.chart.forEach((chartObj) => {
            const chartJson = store_default.getChartJson(chartObj.chart_id);
            chartObj.chartOptions = chartJson;
          });
        }
      });
    }
    return store_default.luckysheetfile;
  }
  function getconfig() {
    return store_default.config;
  }
  function getvisibledatarow() {
    return store_default.visibledatarow;
  }
