  function getRangeDiagonal(type, options = {}) {
    let typeValues = ["normal", "anti", "offset"];
    if (typeValues.indexOf(type) < 0) {
      return tooltip_default.info("The type parameter must be included in ['normal', 'anti', 'offset']", "");
    }
    let curSheetOrder = getSheetIndex(store_default.currentSheetIndex);
    let curRange = JSON.parse(JSON.stringify(store_default.luckysheet_select_save));
    let {
      column = 1,
      range: range2 = curRange,
      order = curSheetOrder
    } = __spreadValues({}, options);
    let file = store_default.luckysheetfile[order];
    let config = file.config;
    if (range2 && typeof range2 === "string" && formula_default.iscelldata(range2)) {
      range2 = formula_default.getcellrange(range2);
    }
    if (!range2 || range2.length > 1) {
      if (isEditMode()) {
        alert(locale_default().drag.noMulti);
      } else {
        tooltip_default.info(locale_default().drag.noMulti, "");
      }
      return;
    }
    if (config["merge"] != null) {
      let has_PartMC = false;
      let r1 = range2[0].row[0], r2 = range2[0].row[1], c1 = range2[0].column[0], c2 = range2[0].column[1];
      has_PartMC = hasPartMC(config, r1, r2, c1, c2);
      if (has_PartMC) {
        if (isEditMode()) {
          alert(locale_default().drag.noPartMerge);
        } else {
          tooltip_default.info(locale_default().drag.noPartMerge, "");
        }
        return;
      }
    }
    let getdata = getdatabyselection(range2, order);
    let arr = [];
    if (getdata.length === 0) {
      return;
    }
    let clen = getdata[0].length;
    switch (type) {
      case "normal":
        for (let r2 = 0; r2 < getdata.length; r2++) {
          if (r2 >= clen) {
            break;
          }
          arr.push(getdata[r2][r2]);
        }
        break;
      case "anti":
        for (let r2 = 0; r2 < getdata.length; r2++) {
          if (r2 >= clen) {
            break;
          }
          arr.push(getdata[r2][clen - r2 - 1]);
        }
        break;
      case "offset":
        if (column.toString() == "NaN") {
          if (isEditMode()) {
            alert(locale_default().drag.inputCorrect);
          } else {
            tooltip_default.info(locale_default().drag.inputCorrect, "");
          }
          return;
        }
        if (column < 0) {
          if (isEditMode()) {
            alert(locale_default().drag.offsetColumnLessZero);
          } else {
            tooltip_default.info(locale_default().drag.offsetColumnLessZero, "");
          }
          return;
        }
        for (let r2 = 0; r2 < getdata.length; r2++) {
          if (r2 + column >= clen) {
            break;
          }
          arr.push(getdata[r2][r2 + column]);
        }
        break;
    }
    selection_default.copybyformat(new Event(), JSON.stringify(arr));
  }
