    if (order <= 0) {
      let beforeIndex = store_default.luckysheetfile[0].index;
      let beforeObj = $("#luckysheet-sheets-item" + beforeIndex);
      $("#luckysheet-sheets-item" + index2).insertBefore(beforeObj);
      store_default.luckysheetfile.splice(0, 0, sheetconfig);
    } else {
      if (order > store_default.luckysheetfile.length) {
        order = store_default.luckysheetfile.length;
      }
      let afterIndex = store_default.luckysheetfile[order - 1].index;
      let afterObj = $("#luckysheet-sheets-item" + afterIndex);
      $("#luckysheet-sheets-item" + index2).insertAfter(afterObj);
      store_default.luckysheetfile.splice(order, 0, sheetconfig);
    }
    let orders = {};
    store_default.luckysheetfile.forEach((item2, i2, arr) => {
      arr[i2].order = i2;
      orders[item2.index.toString()] = i2;
    });
    $("#luckysheet-sheet-area div.luckysheet-sheets-item").removeClass("luckysheet-sheets-item-active");
    $("#luckysheet-sheets-item" + index2).addClass("luckysheet-sheets-item-active");
    $("#luckysheet-cell-main").append('<div id="luckysheet-datavisual-selection-set-' + index2 + '" class="luckysheet-datavisual-selection-set"></div>');
    cleargridelement(true);
    server_default.saveParam("sha", null, $.extend(true, {}, sheetconfig));
    server_default.saveParam("shr", null, orders);
    if (store_default.clearjfundo) {
      store_default.jfundo.length = 0;
      let redo2 = {};
      redo2["type"] = "addSheet";
      redo2["sheetconfig"] = $.extend(true, {}, sheetconfig);
      redo2["index"] = index2;
      redo2["currentSheetIndex"] = store_default.currentSheetIndex;
      store_default.jfredo.push(redo2);
    }
    sheetmanage_default.changeSheetExec(index2, false, true);
    if (success && typeof success === "function") {
      success();
    }
    return sheetconfig;
